def task(robot):
    robot.wave()
    robot.say("What colour drink would you like?")
    desired_colour = robot.listen().lower()
    cans = robot.look()
    target_can = None
    for can in cans:
        if can["colour"].lower() == desired_colour:
            target_can = can
            break
    if target_can:
        robot.pick(target_can["id"])
        robot.give()
    else:
        robot.say("Sorry, I do not have that colour.")

