def task(robot):
    robot.wave()
    cans = robot.look()
    selected_ids = []
    colors = set()

    for can in cans:
        if can['colour'] not in colors:
            selected_ids.append(can['id'])
            colors.add(can['colour'])
        if len(selected_ids) == 2:
            break

    for can_id in selected_ids:
        if robot.pick(can_id):
            robot.give()

def task(robot):
    cans = robot.look()
    sprite_cans = [c for c in cans if c["label"] == "Sprite"]

    if not sprite_cans:
        robot.say("I'm sorry, I don't have any Sprite.")
        return

    closest_can = min(sprite_cans, key=lambda c: (c["x"]**2 + c["y"]**2)**0.5)

    if robot.pick(closest_can["id"]):
        robot.give()
    else:
        robot.say("I couldn't pick up the Sprite.")
